from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_canonical = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entry_date = None
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Never intentionally retain or replace positions on expiration day.
        if self.entry_symbol is not None:
            expiry = self.Securities[self.entry_symbol].Symbol.ID.Date.date()

            if current_date >= expiry:
                self.no_entry_date = current_date
                self._submit_exit("expiration safeguard")

            elif current_date == self._previous_trading_day(expiry):
                if self.Time.time() >= datetime.strptime("15:45", "%H:%M").time():
                    self._submit_exit("pre-expiration time stop")

            self._evaluate_profit_target(slice)

        # Immediately remove any SPY equity created by exercise or assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.no_entry_date = current_date
            if self.spy_liquidation_ticket is None or not self._ticket_open(
                self.spy_liquidation_ticket
            ):
                self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
                self.spy_liquidation_ticket = self.MarketOrder(
                    self.spy, -spy_quantity
                )

        if not slice.Bars.ContainsKey(self.spy):
            return

        minute_bar = slice.Bars[self.spy]
        self._process_minute_bar(minute_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        bar_time = minute_bar.Time
        if bar_time.weekday() >= 5:
            return

        session_start = bar_time.replace(hour=9, minute=30, second=0, microsecond=0)
        session_end = bar_time.replace(hour=16, minute=0, second=0, microsecond=0)

        if bar_time < session_start or bar_time >= session_end:
            return

        minutes_from_open = int((bar_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(minutes_from_open // 5) * 5
        )

        if self.bucket_start != bucket_start:
            if self.bucket_start is not None and self.bucket_bars:
                self._finalize_bucket(slice)

            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

        # A complete regular-session five-minute bar ends at 09:35, 09:40, etc.
        if bar_time == bucket_start + timedelta(minutes=4):
            self._finalize_bucket(slice)
            self.bucket_start = None
            self.bucket_bars = []

    def _finalize_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        # Missing minute data means the five-minute interval is discarded.
        expected_times = {
            self.bucket_start + timedelta(minutes=i) for i in range(5)
        }
        actual_times = {bar.Time for bar in self.bucket_bars}

        if actual_times != expected_times:
            self.Debug(
                "Skipped incomplete SPY five-minute bar ending "
                f"{self.bucket_start + timedelta(minutes=5):%Y-%m-%d %H:%M}."
            )
            return

        ordered = sorted(self.bucket_bars, key=lambda bar: bar.Time)
        consolidated = TradeBar(
            self.bucket_start,
            self.spy,
            ordered[0].Open,
            max(bar.High for bar in ordered),
            min(bar.Low for bar in ordered),
            ordered[-1].Close,
            sum(bar.Volume for bar in ordered),
            timedelta(minutes=5)
        )

        self._on_five_minute_bar(consolidated, slice)

    def _on_five_minute_bar(self, bar: TradeBar, slice: Slice):
        close = float(bar.Close)

        old_fast = self.previous_fast
        old_slow = self.previous_slow

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / len(self.fast_closes)
        slow = sum(self.slow_closes) / len(self.slow_closes)

        bullish_cross = (
            old_fast is not None
            and old_slow is not None
            and old_fast <= old_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = bar.EndTime
        eligible_time = (
            datetime.strptime("09:45", "%H:%M").time()
            <= end_time.time()
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        if not bullish_cross or not eligible_time:
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.entry_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_open(self.entry_ticket):
            return

        self._select_and_enter(slice, close)

    def _select_and_enter(self, slice: Slice, spy_price: float):
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        chains = []
        for chain in slice.OptionChains.Values:
            if chain.Symbol.ID.Symbol == self.option_canonical.ID.Symbol:
                chains.append(chain)

        if not chains:
            self.Debug("Skipped call selection: no current SPY option chain.")
            return

        contracts = []
        for chain in chains:
            for contract in chain:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped call selection: no qualifying call contracts.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        strike_floor = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped call selection: no call strike at least 1% OTM.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Call entry submitted: {selected.Symbol}.")

    def _evaluate_profit_target(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._ticket_open(self.exit_ticket):
            return

        midpoint = self._current_option_midpoint(slice, self.entry_symbol)
        if midpoint is None:
            return

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _current_option_midpoint(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue

                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

                return None

        return None

    def _submit_exit(self, reason: str):
        if self.entry_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._ticket_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order.")

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Call exit submitted: {reason}.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.entry_symbol = order_event.Symbol
                self.Debug(
                    f"Call entry filled: {order_event.Symbol}, "
                    f"price {order_event.FillPrice:.4f}."
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Call entry order did not fill.")
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Call exit filled: {order_event.Symbol}.")
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.no_entry_date = self.Time.date()
        self.Debug("Unexpected option assignment received; liquidating SPY.")
        self._liquidate_spy()

    def OnExerciseOrderEvent(self, exercise_event: OrderEvent):
        self.no_entry_date = self.Time.date()
        self.Debug("Unexpected option exercise received; liquidating SPY.")
        self._liquidate_spy()

    def _liquidate_spy(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if self.spy_liquidation_ticket is None or not self._ticket_open(
            self.spy_liquidation_ticket
        ):
            self.spy_liquidation_ticket = self.MarketOrder(self.spy, -quantity)

    def _previous_trading_day(self, date_value):
        hours = self.Securities[self.spy].Exchange.Hours
        date_time = datetime(date_value.year, date_value.month, date_value.day)

        try:
            previous = hours.GetPreviousTradingDay(date_time)
            return previous.date() if hasattr(previous, "date") else previous
        except Exception:
            # Conservative fallback for ordinary weekends.
            previous = date_value - timedelta(days=1)
            while previous.weekday() >= 5:
                previous -= timedelta(days=1)
            return previous

    def _ticket_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )
