from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-1000, 1000)
                       .Expiration(timedelta(days=0), timedelta(days=730))
        )

        self.closes = RollingWindow[float](20)
        self.fast_average = None
        self.slow_average = None
        self.previous_fast_average = None
        self.previous_slow_average = None

        self.current_bucket_end = None
        self.current_bucket_bars = []
        self.current_bucket_valid = True
        self.last_minute_start = None

        self.latest_spy_price = None

        self.held_option = None
        self.held_option_expiry = None
        self.entry_price = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_cleanup_order_id = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()

        # Never intentionally hold an option into its expiration date.
        if self.held_option is not None and self.held_option_expiry is not None:
            if current_date >= self.held_option_expiry:
                self.no_entry_date = current_date

                if self.entry_order_id is not None:
                    self.Transactions.CancelOrder(
                        self.entry_order_id,
                        "Canceling entry during expiration processing"
                    )
                    self.entry_order_id = None

                if self.exit_order_id is None:
                    self._submit_exit("Expiration liquidation")

        # Evaluate option exits on every minute Slice.
        self._evaluate_option_exits(slice)

        if self.spy not in slice.Bars:
            return

        spy_bar = slice.Bars[self.spy]
        self.latest_spy_price = float(spy_bar.Close)

        completed_bar = self._update_five_minute_bar(spy_bar)
        if completed_bar is None:
            return

        self._process_completed_five_minute_bar(completed_bar, slice)

    def _update_five_minute_bar(self, minute_bar):
        bar_start = minute_bar.Time

        if bar_start.date() != self.Time.date():
            return None

        if not time(9, 30) <= bar_start.time() < time(16, 0):
            return None

        bucket_end = datetime(
            bar_start.year,
            bar_start.month,
            bar_start.day,
            bar_start.hour,
            (bar_start.minute // 5 + 1) * 5,
            0
        )

        completed_bar = None

        if self.current_bucket_end is not None:
            if bucket_end != self.current_bucket_end:
                if (
                    self.current_bucket_valid
                    and len(self.current_bucket_bars) == 5
                ):
