                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        # 21 values are required to compare the current and preceding 20-bar SMAs.
        self.closes = RollingWindow[float](21)

        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None
        self.exit_ticket = None

        self.no_entry_date = None
        self.assignment_liquidation_submitted = False

    def OnData(self, slice: Slice):
        # Never intentionally retain equity received through exercise or assignment.
        if self.Portfolio[self.spy].Quantity != 0:
            if not self.assignment_liquidation_submitted:
                self.Debug("Unexpected exercise/assignment: liquidating SPY")
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity
                )
                self.assignment_liquidation_submitted = True

        # Prevent holding through expiration.
        if self.held_symbol is not None and self.held_expiry is not None:
            if self.Time.date() >= self.held_expiry.date():
                self.no_entry_date = self.Time.date()
                self._submit_exit("expiration")

        if self.spy in slice.Bars:
            self._consume_minute_bar(slice.Bars[self.spy], slice)

        if self.held_symbol is None or self.held_expiry is None:
            return

        current_date = self.Time.date()
        expiry_date = self.held_expiry.date()

        # Independent pre-expiration time stop.
        if self._is_pre_expiry_day(current_date, expiry_date):
            if self.Time.hour == 15 and self.Time.minute == 45:
                self._submit_exit("pre-expiry time stop")

        # Profit target is evaluated on every minute Slice.
        if current_date < expiry_date:
            self._check_profit_target(slice)

    def _consume_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        start = minute_bar.Time.replace(second=0, microsecond=0)
        minutes = start.hour * 60 + start.minute
        bucket_start = (
            start.replace(hour=0, minute=0)
            + timedelta(minutes=(minutes // 5) * 5)
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        elif bucket_start != self.bucket_start:
            self._emit_bucket(slice, self.bucket_start + timedelta(minutes=5))
            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

        expected_end = bucket_start + timedelta(minutes=5)
        actual_end = minute_bar.EndTime.replace(second=0, microsecond=0)

        if actual_end == expected_end:
            self._emit_bucket(slice, actual_end)
            self.bucket_start = None
            self.bucket_bars = []

    def _emit_bucket(self, slice: Slice, end_time: datetime):
        if not self.bucket_bars:
            return

        bars = self.bucket_bars

        consolidated = TradeBar(
            bars[0].Time,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self._on_five_minute_bar(consolidated, slice)

    def _on_five_minute_bar(self, bar: TradeBar, slice: Slice):
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        crossover = (
            previous_fast <= previous_slow
            and fast > slow
        )

        end = bar.EndTime
        eligible_time = (
            (end.hour > 9 or (end.hour == 9 and end.minute >= 45))
            and
            (end.hour < 14 or (end.hour == 14 and end.minute <= 30))
        )

