    def _consume_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        start = minute_bar.Time.replace(second=0, microsecond=0)
        minutes = start.hour * 60 + start.minute
        bucket_start = (
            start.replace(hour=0, minute=0)
            + timedelta(minutes=(minutes // 5) * 5)
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        elif bucket_start != self.bucket_start:
            self._emit_bucket(slice, self.bucket_start + timedelta(minutes=5))
            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

        expected_end = bucket_start + timedelta(minutes=5)
        actual_end = minute_bar.EndTime.replace(second=0, microsecond=0)

        if actual_end == expected_end:
            self._emit_bucket(slice, actual_end)
            self.bucket_start = None
            self.bucket_bars = []

