        option.SetFilter(
            lambda u: u.include_weeklys()
                        .strikes(-200, 200)
                        .expiration(0, 730)
        )
        self.option = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.active_bucket = None
        self.minute_bars = {}

        self.current_chain = None
        self.last_spy_price = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.exit_symbol = None

        self.no_entry_today = False
        self.current_date = None
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.current_date != today:
            self.current_date = today
            self.no_entry_today = False
            self.spy_liquidation_ticket = None

        if self.option in slice.OptionChains:
            self.current_chain = slice.OptionChains[self.option]
        else:
            self.current_chain = None

        self._handle_unexpected_spy_position()

        # Expiration-date protection is evaluated before normal exit logic.
        if self.entry_symbol is not None:
            expiry = self.Securities[self.entry_symbol].Symbol.ID.Date.date()

            if today >= expiry:
                self.no_entry_today = True
                self._submit_exit("expiration protection")

            elif self._is_immediately_prior_trading_day(expiry):
                if self.Time.hour > 15 or (
                    self.Time.hour == 15 and self.Time.minute >= 45
                ):
                    self._submit_exit("pre-expiration time stop")

            else:
                self._check_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        self.last_spy_price = float(minute_bar.Close)
        self._process_minute_bar(minute_bar)

    def _process_minute_bar(self, minute_bar: TradeBar):
        local_time = minute_bar.Time

        if local_time.hour < 9 or (
            local_time.hour == 9 and local_time.minute < 30
        ):
            return

        if local_time.hour >= 16:
            return

        minutes_from_open = (local_time.hour * 60 + local_time.minute) - 570
        bucket_start = datetime(
            local_time.year,
            local_time.month,
            local_time.day,
            9,
            30
        ) + timedelta(minutes=(minutes_from_open // 5) * 5)

        if self.active_bucket != bucket_start:
            if self.active_bucket is not None:
                self._finalize_bucket(self.active_bucket)

            self.active_bucket = bucket_start
            self.minute_bars[bucket_start] = []

        self.minute_bars.setdefault(bucket_start, []).append(minute_bar)

    def _finalize_bucket(self, bucket_start: datetime):
        bars = self.minute_bars.pop(bucket_start, [])

        # Require all five one-minute bars. Never synthesize missing data.
        if len(bars) != 5:
            return

        bars.sort(key=lambda x: x.Time)

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if [bar.Time for bar in bars] != expected_times:
            return

        consolidated = TradeBar(
            bucket_start,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self.fast.Update(consolidated.EndTime, consolidated.Close)
        self.slow.Update(consolidated.EndTime, consolidated.Close)

        if self.fast.IsReady and self.slow.IsReady:
            fast_value = float(self.fast.Current.Value)
            slow_value = float(self.slow.Current.Value)

            bullish_cross = (
                self.previous_fast is not None
                and self.previous_slow is not None
                and self.previous_fast <= self.previous_slow
                and fast_value > slow_value
            )

            bar_end = consolidated.EndTime
            eligible_time = (
                datetime(1900, 1, 1, 9, 45).time()
                <= bar_end.time()
                <= datetime(1900, 1, 1, 14, 30).time()
            )

            if (
                bullish_cross
                and eligible_time
                and not self.no_entry_today
                and self.entry_symbol is None
                and not self._entry_order_open()
            ):
                self._try_enter()

            self.previous_fast = fast_value
            self.previous_slow = slow_value

    def _try_enter(self):
        if self.current_chain is None:
            self.Debug("Skipped entry: no current option chain.")
            return

        if self.last_spy_price is None or self.last_spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        algorithm_date = self.Time.date()

        candidates = []
        for contract in self.current_chain:
            if contract.Right != OptionRight.Call:
                continue

            expiry_date = contract.Expiry.date()
            if (expiry_date - algorithm_date).days < 7:
                continue

            candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no call expiration at least 7 days out.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        threshold = 1.01 * self.last_spy_price

        strike_candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
            and float(contract.Strike) >= threshold
        ]

        if not strike_candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY MA crossover entry"
        )

        self.Debug(
            "Submitted entry: {} strike {:.2f} expiry {}".format(
                selected.Symbol,
                float(selected.Strike),
                nearest_expiry
            )
        )

    def _check_profit_target(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        if self.current_chain is None:
            return

        held_contract = None
        for contract in self.current_chain:
            if contract.Symbol == self.entry_symbol:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        if self._exit_order_open():
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            quantity = 1

        self.exit_symbol = self.entry_symbol
        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Submitted exit for {}: {}".format(
                self.entry_symbol,
                reason
            )
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _is_immediately_prior_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, datetime.min.time())
        ):
            candidate -= timedelta(days=1)

        return self.Time.date() == candidate

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        self.no_entry_today = True

        if (
            self.spy_liquidation_ticket is None
            or self.spy_liquidation_ticket.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.Debug(
                "Unexpected SPY equity position detected; liquidating "
                "immediately."
            )
            self.spy_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def OnAssignmentOrderEvent(self, assignment_event):
        self.no_entry_today = True
        self.Debug("Unexpected option exercise or assignment detected.")

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.spy_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Exercise or assignment SPY liquidation"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                if self.entry_price is None:
                    self.entry_price = float(order_event.FillPrice)

                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Entry filled: {} at {:.4f}".format(
                            self.entry_symbol,
                            self.entry_price
                        )
                    )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        float(order_event.FillPrice)
                    )
                )
                self.entry_symbol = None
                self.entry_price = None
                self.entry_ticket = None
                self.exit_ticket = None
                self.exit_symbol = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None
                self.exit_symbol = None
