        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )

        self.closes = deque(maxlen=20)
        self.current_bucket_start = None
        self.current_bucket_bars = {}

        self.previous_fast = None
        self.previous_slow = None

        self.held_contract = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None

        self.no_entry_date = None
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.no_entry_date != today:
            self.no_entry_date = None

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(today)
        self._evaluate_open_position_exit(slice, today)
        self._process_spy_minute_bar(slice)

    def _process_spy_minute_bar(self, slice: Slice):
        if self.spy_symbol not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy_symbol]
        local_end = minute_bar.EndTime.astimezone(self.TimeZone)
        local_start = local_end - timedelta(minutes=1)

        if local_start.time() < time(9, 30) or local_start.time() >= time(16, 0):
            return

        minutes_from_open = (local_start.hour * 60 + local_start.minute) - (9 * 60 + 30)
        bucket_number = minutes_from_open // 5
        bucket_start = datetime.combine(
            local_start.date(), time(9, 30)
        ) + timedelta(minutes=bucket_number * 5)

        if (
            self.current_bucket_start is not None
            and bucket_start != self.current_bucket_start
        ):
            self._emit_five_minute_bar_if_complete()

        if self.current_bucket_start != bucket_start:
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = {}

        self.current_bucket_bars[local_start] = minute_bar

    def _emit_five_minute_bar_if_complete(self):
        if self.current_bucket_start is None:
            return

        expected_times = [
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self.current_bucket_bars for t in expected_times):
            self.current_bucket_bars = {}
            return

        bars = [self.current_bucket_bars[t] for t in expected_times]
        close = bars[-1].Close
        bar_end = self.current_bucket_start + timedelta(minutes=5)

        self._update_moving_averages(close, bar_end)

        self.current_bucket_bars = {}

    def _update_moving_averages(self, close: float, bar_end: datetime):
        if len(self.closes) == 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(float(close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_time = bar_end.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if crossover and eligible_time:
            self._try_enter_call()

    def _try_enter_call(self):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_contract is not None:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if self._has_any_option_holding():
            return

        if self.spy_symbol not in self.Securities:
            return

        spy_price = self.Securities[self.spy_symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        contracts = []
        for chain in self.CurrentSlice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date < today + timedelta(days=7):
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped selection: no eligible call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={nearest_expiry}, strike={selected.Strike}"
        )

    def _evaluate_open_position_exit(self, slice: Slice, today: date):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        expiry_date = self.held_contract.ID.Date.date()

        time_stop = (
            today == expiry_date - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        )

        if time_stop:
            self._liquidate_option("time stop")
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if self.held_contract not in slice.OptionQuotes:
            return

        quote = slice.OptionQuotes[self.held_contract]
        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0 or self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason: str):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_contract, -quantity, tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_contract}, reason={reason}")

    def _handle_expiration_processing(self, today: date):
        if self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()

        if today >= expiry_date:
            self.no_entry_date = today

            if self._ticket_is_open(self.entry_ticket):
                self.entry_ticket.Cancel("Expiration processing")

            self._liquidate_option("expiration protection")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity

        if quantity == 0:
            return

        if self._ticket_is_open(self.spy_liquidation_ticket):
            return

        self.Debug(
            f"Unexpected SPY equity position detected: quantity={quantity}; "
            "liquidating."
        )
        self.spy_liquidation_ticket = self.MarketOrder(
            self.spy_symbol, -quantity, tag="Unexpected exercise or assignment"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)

        is_assignment = getattr(order_event, "IsAssignment", False)
        is_exercise = order.Type == OrderType.OptionExercise

        if is_assignment or is_exercise:
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected exercise or assignment processed.")
            self._handle_unexpected_spy_position()

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_contract = order.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"Entry filled: {self.held_contract}, "
                        f"price={self.entry_price}"
                    )

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.Debug("Entry order canceled or invalid.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order.Symbol}, "
                        f"price={order_event.FillPrice}"
                    )
                    self.held_contract = None
                    self.entry_price = None
                    self.exit_ticket = None

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.exit_ticket = None

    def _has_any_option_holding(self):
        for security in self.Portfolio:
            symbol = security.Key
            if symbol.SecurityType == SecurityType.Option and security.Value.Invested:
                return True
        return False

    @staticmethod
    def _ticket_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted,
        )
