            candidate_datetime = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )

            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                candidate_datetime
            ):
                return candidate

            candidate -= timedelta(days=1)

    def OnOrderEvent(self, order_event):
        if (
            self.entry_order_id is not None and
            order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None

                self.Debug(
                    f"Entry filled: {self.held_option.Value}, "
                    f"price={self.entry_price}"
                )

            elif order_event.Status in {
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.CancelPending
            }:
                if order_event.Status != OrderStatus.CancelPending:
                    self.entry_order_id = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol.Value}, "
                    f"price={order_event.FillPrice}"
                )
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None

            elif order_event.Status in {
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }:
                self.exit_ticket = None

        # Handle unexpected option exercise or assignment.
        if bool(getattr(order_event, "IsAssignment", False)):
            self.Debug(
                f"Unexpected exercise or assignment: "
                f"{order_event.Symbol.Value}"
            )

            equity_quantity = self.Portfolio[self.spy].Quantity

            if equity_quantity != 0 and self.equity_cleanup_order_id is None:
                cleanup_ticket = self.MarketOrder(
                    self.spy,
                    -equity_quantity,
                    tag="Unexpected exercise/assignment cleanup"
                )
                self.equity_cleanup_order_id = cleanup_ticket.OrderId

    def OnEndOfAlgorithm(self):
        self.SubscriptionManager.RemoveConsolidator(
            self.spy,
            self.consolidator
        )


def time_is_at_or_after(value, hour, minute):
    return (value.hour, value.minute) >= (hour, minute)


def time_is_at_or_before(value, hour, minute):
    return (value.hour, value.minute) <= (hour, minute)


def time_is_between_inclusive(value, start_hour, start_minute,
                              end_hour, end_minute):
    return (
        (value.hour, value.minute) >= (start_hour, start_minute) and
        (value.hour, value.minute) <= (end_hour, end_minute)
    )
