        option.SetFilter(
            lambda u: u.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )
        self.option = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_start = None
        self.bucket_bars = {}
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration = None
        self.pre_expiration_trading_day = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY exercise/assignment; liquidating SPY")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
            self.no_entry_date = self.Time.date()

        now = self.Time

        if self.held_symbol is not None:
            invested = self.Portfolio[self.held_symbol].Invested

            if invested:
                if self.expiration is not None and now.date() >= self.expiration:
                    self.no_entry_date = now.date()
                    self._submit_exit("expiration")
                elif (
                    self.pre_expiration_trading_day == now.date()
                    and now.time() >= time(15, 45)
                ):
                    self._submit_exit("time stop")
                else:
                    quote = self._current_quote(slice, self.held_symbol)
                    if quote is not None and self.entry_price is not None:
                        bid, ask = quote
                        midpoint = (bid + ask) / 2.0

                        if midpoint >= 1.50 * self.entry_price:
                            self._submit_exit("profit target")

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._accept_minute_bar(bar, slice)

    def _accept_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime
        current_date = end.date()
        session_start = end.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        session_end = end.replace(
            hour=16, minute=0, second=0, microsecond=0
        )

        if end <= session_start or end > session_end:
            return

        elapsed_minutes = int(
            (end - session_start).total_seconds() // 60
        )
        bucket_start = session_start + timedelta(
