from AlgorithmImports import *

from collections import deque
from datetime import datetime, timedelta, time


class SpyLongCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(
            DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(timedelta(days=0), timedelta(days=730))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.bucket_date = None
        self.bucket_index = None
        self.bucket_bars = {}

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.no_entry_dates = set()
        self.exercise_handled_dates = set()

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        self._handle_unexpected_equity_position(today)

        if self.held_symbol is not None:
            quantity = self.Portfolio[self.held_symbol].Quantity

            if quantity == 0:
                self._clear_position_state()
            else:
                expiration_date = self._expiration_date(self.held_symbol)

                if expiration_date is not None and today >= expiration_date:
                    self.no_entry_dates.add(today)
                    self._submit_exit("expiration processing")

                elif (
                    expiration_date is not None
                    and now.hour == 15
                    and now.minute == 45
                    and today == self._previous_trading_day(expiration_date)
                ):
                    self._submit_exit("expiration time stop")

                else:
                    self._evaluate_profit_target(slice)

        bar = self._consume_minute_bar(slice)
        if bar is not None:
            self._process_five_minute_bar(bar, slice)

    def _consume_minute_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return None

        minute_bar = slice.Bars[self.spy]
        local_time = self.Time
        local_date = local_time.date()
        minute_of_day = local_time.hour * 60 + local_time.minute

        regular_open = 9 * 60 + 30
        regular_close = 16 * 60

        if minute_of_day < regular_open or minute_of_day >= regular_close:
            return None

        bucket_index = (minute_of_day - regular_open) // 5

        if self.bucket_date != local_date or self.bucket_index != bucket_index:
            completed = self._complete_bucket()

            self.bucket_date = local_date
            self.bucket_index = bucket_index
            self.bucket_bars = {}

            if completed is not None:
                self._pending_completed_bar = completed
            else:
                self._pending_completed_bar = None
        else:
            self._pending_completed_bar = None

        self.bucket_bars[minute_of_day] = minute_bar

        completed = getattr(self, "_pending_completed_bar", None)
        self._pending_completed_bar = None
        return completed

    def _complete_bucket(self):
        if self.bucket_date is None or self.bucket_index is None:
            return None

        start_minute = 9 * 60 + 30 + self.bucket_index * 5
        expected_minutes = set(range(start_minute, start_minute + 5))

        if set(self.bucket_bars.keys()) != expected_minutes:
            return None

        bars = [self.bucket_bars[m] for m in sorted(self.bucket_bars)]

        end_hour = (start_minute + 5) // 60
        end_minute = (start_minute + 5) % 60
        end_time = datetime(
            self.bucket_date.year,
            self.bucket_date.month,
            self.bucket_date.day,
            end_hour,
            end_minute
        )

        return TradeBar(
            end_time,
            self.spy,
            bars[0].Open,
            max(float(x.High) for x in bars),
            min(float(x.Low) for x in bars),
            bars[-1].Close,
            sum(int(x.Volume) for x in bars),
            timedelta(minutes=5)
        )

    def _process_five_minute_bar(self, bar: TradeBar, slice: Slice):
        prior_fast = None
        prior_slow = None

        if len(self.closes) >= self.slow_period:
            prior_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            prior_slow = sum(self.closes) / self.slow_period

        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        crossover = (
            prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        bar_end = bar.EndTime
        if bar_end.tzinfo is not None:
            bar_end = bar_end.replace(tzinfo=None)

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if crossover and eligible_time:
            self._try_enter(slice, float(bar.Close), bar_end.date())

    def _try_enter(self, slice: Slice, spy_price: float, algorithm_date):
        if algorithm_date in self.no_entry_dates:
            return

        if self.held_symbol is not None:
            return

        if self._order_is_open(self.entry_ticket):
            return

        if self.option.Symbol not in slice.OptionChains:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option.Symbol]
        minimum_expiration = algorithm_date + timedelta(days=7)

        calls = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiration
            and contract.Strike >= 1.01 * spy_price
        ]

        if not calls:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        nearest_expiration = min(
            contract.Expiry.date() for contract in calls
        )

        candidates = [
            contract
            for contract in calls
            if contract.Expiry.date() == nearest_expiration
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiration={nearest_expiration} strike={selected.Strike}"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._order_is_open(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason} symbol={self.held_symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.entry_ticket = None
                    self.Debug(
                        f"Entry filled: {self.held_symbol} "
                        f"price={self.entry_price}"
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol} "
                        f"price={order_event.FillPrice}"
                    )
                    self.exit_ticket = None
                    self._clear_position_state()
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def OnAssignmentOrder(self, assignment_order_event: OrderEvent):
        self.Debug(
            f"Unexpected option exercise or assignment: "
            f"{assignment_order_event.Symbol}"
        )
        self.no_entry_dates.add(self.Time.date())

    def _handle_unexpected_equity_position(self, today):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            if today not in self.exercise_handled_dates:
                self.Debug(
                    f"Unexpected exercise or assignment created SPY position: "
                    f"quantity={quantity}"
                )
                self.exercise_handled_dates.add(today)
                self.no_entry_dates.add(today)

            self.MarketOrder(self.spy, -quantity, tag="Unexpected assignment liquidation")

    def _expiration_date(self, symbol):
        if symbol is None:
            return None

        try:
            return symbol.ID.Date.date()
        except Exception:
            try:
                return self.Securities[symbol].Symbol.ID.Date.date()
            except Exception:
                return None

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    def _order_is_open(self, ticket):
