        end = bar.EndTime
        minute_number = end.hour * 60 + end.minute
        bucket_end_minutes = ((minute_number + 4) // 5) * 5

        bucket_end = datetime(
            end.year,
            end.month,
            end.day
        ) + timedelta(minutes=bucket_end_minutes)

        if self._bucket_end != bucket_end:
