            selected.Symbol,
            1,
            tag="SPY call crossover entry"
        )
        self._entry_order_id = self._entry_ticket.OrderId

    def _EvaluateProfitTarget(self):
        if self._held_option is None or self._entry_price is None:
            return

        if self._IsTicketOpen(self._exit_ticket):
            return

        contract = self._GetHeldContract()
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self._SubmitExit("50% profit target")

    def _HandleExpirationProcessing(self):
        if self._held_option is None:
            return

        expiry_date = self._held_option.Expiry.date()
        today = self.Time.date()

        if today >= expiry_date:
            self._blocked_entry_date = today
            self._SubmitExit("expiration protection")
            return

        previous_trading_day = self._PreviousTradingDay(expiry_date)

        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._SubmitExit("pre-expiration time stop")

    def _SubmitExit(self, reason: str):
        if self._held_option is None:
            return

        if self._IsTicketOpen(self._exit_ticket):
            return

        quantity = self.Portfolio[self._held_option.Symbol].Quantity
        if quantity == 0:
            return

        if self._entry_ticket is not None:
            self._CancelTicketIfOpen(self._entry_ticket)

        self._CancelTicketIfOpen(self._exit_ticket)

        self._exit_ticket = self.MarketOrder(
            self._held_option.Symbol,
            -quantity,
            tag="SPY call exit: " + reason
        )

        self.Debug(
            "Exit submitted: {} {}".format(
                self._held_option.Symbol,
                reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self._held_option = self.Securities[order_event.Symbol]
                self._entry_price = order_event.FillPrice
                self._entry_ticket = None

                self.Debug(
                    "Call entry filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_ticket = None
                self._entry_order_id = None

        if (
            self._held_option is not None
            and order_event.Symbol == self._held_option.Symbol
            and order_event.Status == OrderStatus.Filled
            and order_event.Direction == OrderDirection.Sell
        ):
            self.Debug("Call exit filled: {}".format(order_event.Symbol))
            self._held_option = None
            self._entry_price = None
            self._exit_ticket = None

        message = str(order_event).lower()
        is_exercise_or_assignment = (
            bool(getattr(order_event, "IsAssignment", False))
            or bool(getattr(order_event, "IsExercise", False))
            or "assignment" in message
            or "exercise" in message
        )

        if is_exercise_or_assignment:
            self.Debug("Unexpected exercise or assignment handling.")
            self._HandleUnexpectedSpyPosition()

    def _HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if not self._assignment_liquidation_submitted:
            self.Debug("Unexpected SPY equity position; liquidating.")
            self.MarketOrder(self.spy, -quantity)
            self._assignment_liquidation_submitted = True

    def _GetCurrentOptionChain(self):
        if self._current_slice is None:
            return None

        chains = self._current_slice.OptionChains

        if self.spy_option.Symbol in chains:
            return chains[self.spy_option.Symbol]

        for chain in chains.Values:
            return chain

        return None

    def _GetHeldContract(self):
        chain = self._GetCurrentOptionChain()
        if chain is None:
            return None

        for contract in self._GetContracts(chain):
            if contract.Symbol == self._held_option.Symbol:
                return contract

        return None

    def _GetContracts(self, chain):
        contracts = chain.Contracts
        return list(contracts.Values)

    def _PreviousTradingDay(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _IsTicketOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _CancelTicketIfOpen(self, ticket):
        if self._IsTicketOpen(ticket):
            ticket.Cancel("Replaced by liquidation order")
