        if self._held_option is None or self._entry_price is None:
            return

        if self._IsTicketOpen(self._exit_ticket):
            return

        contract = self._GetHeldContract()
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self._SubmitExit("50% profit target")

    def _HandleExpirationProcessing(self):
        if self._held_option is None:
            return

        expiry_date = self._held_option.Expiry.date()
        today = self.Time.date()

        if today >= expiry_date:
            self._blocked_entry_date = today
            self._SubmitExit("expiration protection")
            return

        previous_trading_day = self._PreviousTradingDay(expiry_date)

        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._SubmitExit("pre-expiration time stop")

    def _SubmitExit(self, reason: str):
        if self._held_option is None:
            return

        if self._IsTicketOpen(self._exit_ticket):
            return

        quantity = self.Portfolio[self._held_option.Symbol].Quantity
        if quantity == 0:
            return

        if self._entry_ticket is not None:
            self._CancelTicketIfOpen(self._entry_ticket)

        self._CancelTicketIfOpen(self._exit_ticket)

        self._exit_ticket = self.MarketOrder(
            self._held_option.Symbol,
            -quantity,
            tag="SPY call exit: " + reason
        )

