    def _HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if not self._assignment_liquidation_submitted:
            self.Debug("Unexpected SPY equity position; liquidating.")
            self.MarketOrder(self.spy, -quantity)
            self._assignment_liquidation_submitted = True

    def _GetCurrentOptionChain(self):
        if self._current_slice is None:
            return None

        chains = self._current_slice.OptionChains

        if self.spy_option.Symbol in chains:
            return chains[self.spy_option.Symbol]

        for chain in chains.Values:
            return chain

        return None

    def _GetHeldContract(self):
        chain = self._GetCurrentOptionChain()
        if chain is None:
            return None

        for contract in self._GetContracts(chain):
            if contract.Symbol == self._held_option.Symbol:
                return contract

        return None

    def _GetContracts(self, chain):
        contracts = chain.Contracts
        return list(contracts.Values)

    def _PreviousTradingDay(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _IsTicketOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _CancelTicketIfOpen(self, ticket):
        if self._IsTicketOpen(ticket):
