        if slice.Bars.ContainsKey(self.spy):
            minute_bar = slice.Bars[self.spy]
            bucket_start = minute_bar.Time.replace(
                minute=(minute_bar.Time.minute // 5) * 5,
                second=0,
                microsecond=0
            )
            self.minute_counts[bucket_start] = (
                self.minute_counts.get(bucket_start, 0) + 1
            )

