            )
            self.MarketOrder(
                self.spy,
                -spy_quantity,
                tag="Unexpected exercise/assignment liquidation"
            )
            self.no_entry_date = today

        # Never intentionally hold an option into expiration.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_date = today
                self.CancelOpenEntryOrder()
                self.SubmitExit("Expiration liquidation")

            else:
                # Time stop on the trading day immediately before expiration.
                prior_trading_day = self.PreviousTradingDay(expiry_date)

                if (
                    today == prior_trading_day
                    and now.time() >= time(15, 45)
                ):
                    self.SubmitExit("Pre-expiration time stop")
                else:
                    self.CheckProfitTarget(slice)

        # Evaluate the crossover entry once after the eligible bar closes.
        if (
            self.pending_signal_time is not None
            and now >= self.pending_signal_time
        ):
            signal_time = self.pending_signal_time
            self.pending_signal_time = None

            if (
                self.no_entry_date != today
                and self.held_option is None
                and not self.IsEntryOrderOpen()
            ):
                self.TryEnter(slice, signal_time)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        end_time = bar.EndTime

        if end_time.time() < time(9, 35):
            return

        if end_time.time() > time(16, 0):
            return

        bucket_start = bar.Time.replace(
            minute=(bar.Time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        # Do not use a partial consolidated bar.
        if self.minute_counts.pop(bucket_start, 0) != 5:
            self.Debug(
                f"Skipped incomplete five-minute SPY bar ending {end_time}."
