        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime
        if end.tzinfo is not None:
            end = end.replace(tzinfo=None)

        # Only regular-session SPY bars are used.
        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return

        bucket_end = end.replace(
            minute=((end.minute - 1) // 5 + 1) * 5,
            second=0,
            microsecond=0
        )

        if bucket_end.time() > time(16, 0):
            return

        if self.current_bucket_end != bucket_end:
            if self.current_bucket_end is not None:
                self._finish_bucket(self.current_bucket_end, slice)

            self.current_bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end] = bar

        if end == bucket_end:
            self._finish_bucket(bucket_end, slice)
            self.current_bucket_end = None
            self.bucket_bars = {}

    def _finish_bucket(self, bucket_end, slice: Slice):
        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        # Missing minute data invalidates the entire five-minute bar.
        if any(t not in self.bucket_bars for t in expected):
            return

        bars = [self.bucket_bars[t] for t in expected]
        close = bars[-1].Close

        previous_ready = len(self.closes) >= 20
        if previous_ready:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(float(close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        if not previous_ready:
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        bar_time = bucket_end.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if (
            bullish_cross and
            eligible_time and
            self.Time.date() not in self.expiration_block_dates and
            self.held_symbol is None and
            not self._entry_order_open()
        ):
            self._enter_from_current_chain(slice, float(close))

