        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None and not self._ticket_is_open(self.exit_ticket):
            self.exit_ticket = None

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(f"Call exit submitted ({reason}): {self.held_symbol}")

    def _get_current_option_quote(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract.BidPrice, contract.AskPrice
        return None

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None and
            self._ticket_is_open(self.entry_ticket)
        )

    def _ticket_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _is_trading_day_immediately_before(self, expiry, current):
        candidate = expiry - timedelta(days=1)

