            candidate -= timedelta(days=1)

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity > 0 and self.equity_liquidation_ticket is None:
            self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity
            )

    def OnAssignmentOrderEvent(self, assignmentEvent):
        self.Debug(f"Unexpected assignment received: {assignmentEvent.Symbol}")
        self._handle_unexpected_spy_position()

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if (
            self.entry_ticket is not None and
            orderEvent.OrderId == self.entry_ticket.OrderId and
            orderEvent.Status == OrderStatus.Filled
        ):
            self.held_symbol = orderEvent.Symbol
            self.entry_price = orderEvent.FillPrice
            self.entry_ticket = None
            self.Debug(
                f"Call entry filled: {self.held_symbol}, "
                f"price={self.entry_price}"
            )

        if (
            self.exit_ticket is not None and
            orderEvent.OrderId == self.exit_ticket.OrderId and
            orderEvent.Status == OrderStatus.Filled
        ):
            self.Debug(f"Call exit filled: {orderEvent.Symbol}")
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None

        if (
            self.equity_liquidation_ticket is not None and
            orderEvent.OrderId == self.equity_liquidation_ticket.OrderId and
            orderEvent.Status == OrderStatus.Filled
        ):
            self.Debug("Unexpected SPY position liquidated.")
            self.equity_liquidation_ticket = None
