from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            fillForward=False,
            dataNormalizationMode=DataNormalizationMode.Raw,
            extendedMarketHours=False
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, fillForward=False)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.current_bucket_end = None
        self.current_bucket = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiry_date = None
        self.time_stop_date = None
        self.blocked_dates = set()

    def OnData(self, data: Slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position(today)

        if self.held_symbol is not None and self.expiry_date is not None:
            if today >= self.expiry_date:
                self.blocked_dates.add(today)
                self._submit_exit("expiration processing")
            elif (
                self.time_stop_date == today
                and self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("expiration time stop")

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, data)

        if self.held_symbol is not None:
            self._check_profit_target(data)

    def _process_minute_bar(self, bar: TradeBar, data: Slice):
        end_time = bar.EndTime
        current_date = end_time.date()
        current_time = end_time.time()

        session_start = time(9, 30)
        session_end = time(16, 0)

        if current_time <= session_start or current_time > session_end:
            return

        start_dt = datetime.combine(current_date, session_start)
        elapsed_minutes = int((end_time - start_dt).total_seconds() // 60)
        bucket_number = (elapsed_minutes + 4) // 5
        bucket_end = start_dt + timedelta(minutes=bucket_number * 5)

        if self.current_bucket_end != bucket_end:
            self._finalize_bucket(data)
            self.current_bucket_end = bucket_end
            self.current_bucket = {}

        minute_key = end_time
        self.current_bucket[minute_key] = bar

        if end_time == bucket_end:
            self._finalize_bucket(data)
            self.current_bucket_end = None
            self.current_bucket = {}

    def _finalize_bucket(self, data: Slice):
        if self.current_bucket_end is None:
            return

        if len(self.current_bucket) != 5:
            return

        bars = sorted(self.current_bucket.values(), key=lambda b: b.EndTime)

        expected_times = [
            self.current_bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if [b.EndTime for b in bars] != expected_times:
            return

        consolidated = TradeBar(
            bars[0].Time,
            self.spy,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

        self._on_five_minute_bar(consolidated, data)

    def _on_five_minute_bar(self, bar: TradeBar, data: Slice):
        self.closes.append(float(bar.Close))

        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period + 1:
            return

        previous_fast = sum(self.closes[-self.fast_period - 1:-1]) / self.fast_period
        previous_slow = sum(self.closes[-self.slow_period - 1:-1]) / self.slow_period
        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter(data)

    def _try_enter(self, data: Slice):
        today = self.Time.date()

        if today in self.blocked_dates:
            return

        if self._has_option_holding() or self._entry_order_open():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped call selection: option chain unavailable.")
            return

        minimum_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        expiry_date = expirations[0]
        spy_price = float(self.Securities[self.spy].Price)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry_date
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.expiry_date = expiry_date
        self.time_stop_date = self._previous_trading_day(expiry_date)

    def _check_profit_target(self, data: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (c for c in chain if c.Symbol == self.held_symbol),
            None
        )

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._order_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {} ({})".format(
                self.held_symbol, reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        self.entry_price
                    )
                )

            if not self._order_open(self.entry_ticket):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.FillQuantity != 0:
                self.Debug(
                    "Call position exit filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        float(order_event.FillPrice)
                    )
                )

            if not self._order_open(self.exit_ticket):
                self.exit_ticket = None
                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiry_date = None
                    self.time_stop_date = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        today = self.Time.date()
        self.blocked_dates.add(today)
        self.Debug("Unexpected option exercise or assignment detected.")

        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Liquidate unexpected assigned SPY shares"
            )

    def _handle_unexpected_spy_position(self, today):
        holding = self.Portfolio[self.spy]

        if holding.Quantity != 0:
            self.blocked_dates.add(today)
            self.Debug("Unexpected SPY equity position detected; liquidating.")
            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Liquidate unexpected SPY equity position"
            )

    def _has_option_holding(self):
        for security in self.Securities.Values:
            if security.Symbol.SecurityType != SecurityType.Option:
                continue

            if self.Portfolio[security.Symbol].Invested:
                return True

        return False

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self._order_open(self.entry_ticket)
        )

    @staticmethod
    def _order_open(ticket):
        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Rejected
        )

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

