        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.entry_symbol is not None:
            return

        if self.entry_ticket is not None and self.IsOrderOpen(self.entry_ticket):
            return

        if self.current_slice is None:
            return

        if not self.current_slice.Bars.ContainsKey(self.spy):
            self.Debug(f"{self.Time}: skipped entry; SPY bar unavailable.")
            return

        spy_price = self.current_slice.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug(f"{self.Time}: skipped entry; invalid SPY price.")
            return

        required_strike = 1.01 * spy_price
        minimum_expiration = today + timedelta(days=7)

        candidates = []

        for chain in self.current_slice.OptionChains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiration_date = contract.Expiry.date()

                if expiration_date < minimum_expiration:
                    continue

                if contract.Strike < required_strike:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug(
                f"{self.Time}: skipped option selection; no qualifying call."
            )
            return

        nearest_expiration = min(
            contract.Expiry.date() for contract in candidates
        )

        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiration
        ]

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_symbol = selected.Symbol
        self.entry_expiration = selected.Expiry.date()
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(
            self.entry_symbol,
            1
        )

        self.Debug(
            f"{self.Time}: entered call order for {self.entry_symbol}."
        )

    def CheckProfitTarget(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        held_contract = None

        for chain in slice.OptionChains:
            for contract in chain:
                if contract.Symbol == self.entry_symbol:
                    held_contract = contract
                    break
            if held_contract is not None:
                break

        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.entry_symbol is None:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity <= 0:
            return

        self.CancelOtherExitOrders()

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity
        )

        self.Debug(
            f"{self.Time}: submitted exit for {self.entry_symbol}; "
            f"reason={reason}."
        )

    def CancelOtherExitOrders(self):
        if self.entry_symbol is None:
            return

        for order in self.Transactions.GetOpenOrders(self.entry_symbol):
            if self.entry_ticket is not None and order.Id == self.entry_ticket.OrderId:
                continue

            self.Transactions.CancelOrder(order.Id)

    def IsOrderOpen(self, ticket):
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if (
            self.entry_ticket is not None
            and orderEvent.OrderId == self.entry_ticket.OrderId
        ):
            if orderEvent.Status == OrderStatus.Filled:
                self.entry_price = orderEvent.FillPrice
                self.Debug(
                    f"{self.Time}: call entry filled at "
                    f"{self.entry_price:.4f}."
                )
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug(
                    f"{self.Time}: call entry order did not fill; "
                    f"status={orderEvent.Status}."
                )
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None
                self.entry_expiration = None

        if (
            self.exit_ticket is not None
            and orderEvent.OrderId == self.exit_ticket.OrderId
            and orderEvent.Status == OrderStatus.Filled
        ):
            self.Debug(
                f"{self.Time}: exited {self.entry_symbol} at "
                f"{orderEvent.FillPrice:.4f}."
            )
            self.ClearPositionState()

        order_type = getattr(orderEvent, "OrderType", None)
        is_assignment = getattr(orderEvent, "IsAssignment", False)
        is_exercise = order_type == OrderType.OptionExercise

        if is_assignment or is_exercise:
            self.blocked_entry_date = self.Time.date()
            self.Debug(
                f"{self.Time}: unexpected option exercise/assignment; "
                f"liquidating SPY equity."
            )

            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                self.MarketOrder(self.spy, -quantity)

    def OnAssignmentOrderEvent(self, assignmentEvent):
        self.blocked_entry_date = self.Time.date()
        self.Debug(
            f"{self.Time}: unexpected assignment event; liquidating SPY."
        )

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy, -quantity)

    def ClearPositionState(self):
        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.entry_expiration = None
        self.exit_ticket = None
