        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.builder = FiveMinuteCloseBuilder(self.OnFiveMinuteBar)

        self.pending_signal = False
        self.pending_signal_time = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.expiration_date = None
        self.time_stop_date = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, bar_end, close):
        previous_ready = self.fast.IsReady and self.slow.IsReady

        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(IndicatorDataPoint(bar_end, close))
        self.slow.Update(IndicatorDataPoint(bar_end, close))

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_crossover = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        local_time = bar_end.time()
        eligible_time = (
            local_time >= datetime.min.time().replace(hour=9, minute=45) and
            local_time <= datetime.min.time().replace(hour=14, minute=30)
        )

        if bullish_crossover and eligible_time:
            self.pending_signal = True
            self.pending_signal_time = bar_end

    def OnData(self, slice):
        today = self.Time.date()
        now = self.Time.time()

        self.HandleUnexpectedSpyPosition(today)

        # Never intentionally carry an option into expiration.
        if self.held_option is not None and self.expiration_date is not None:
            if today >= self.expiration_date:
                self.no_entry_date = today
                self.SubmitExit("expiration processing")
                return

        if self.held_option is not None:
            self.EvaluateExit(slice, today, now)

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is not None:
            self.builder.update(spy_bar)

        # Process each crossover signal once, immediately after its bar closes.
        if not self.pending_signal:
            return

        signal_time = self.pending_signal_time
        self.pending_signal = False
        self.pending_signal_time = None

        if signal_time.date() != today:
            return

        if (
            self.held_option is not None or
            self.HasOpenEntryOrder() or
            self.no_entry_date == today
        ):
            return

        self.TryEnter(slice, today)

    def TryEnter(self, slice, today):
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        spy_price = self.Securities[self.spy_symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_expiry = today + timedelta(days=7)

        contracts = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug("Skipped call selection: no qualifying call contracts.")
            return

        expirations = sorted(
            {contract.Expiry.date() for contract in contracts}
        )
        expiry = expirations[0]

        minimum_strike = spy_price * 1.01

        strikes = [
            contract for contract in contracts
            if contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not strikes:
            self.Debug("Skipped call selection: no call strike at least 1% OTM.")
            return

        selected = sorted(
            strikes,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

        self.expiration_date = expiry
        self.time_stop_date = self.GetPreviousTradingDate(expiry)

    def EvaluateExit(self, slice, today, now):
        if self.held_option is None:
            return

        if self.HasOpenExitOrder():
            return

        # Time stop at or after 15:45 NY time on the preceding trading day.
        if (
            self.time_stop_date is not None and
            today == self.time_stop_date and
            now >= datetime.min.time().replace(hour=15, minute=45)
        ):
            self.SubmitExit("pre-expiration time stop")
            return

        contract = slice.OptionChains.get(self.option_symbol)
        quote = None

        if contract is not None:
            for option_contract in contract.Contracts.Values:
                if option_contract.Symbol == self.held_option:
                    quote = option_contract
                    break

        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.HasOpenExitOrder():
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def HasOpenEntryOrder(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]
        )

    def HasOpenExitOrder(self):
        return (
            self.exit_ticket is not None and
            self.exit_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]
        )

    def GetPreviousTradingDate(self, date_value):
        candidate = date_value - timedelta(days=1)

        while True:
            test_time = datetime(
                candidate.year,
                candidate.month,
                candidate.day,
                12,
                0,
                0
            )

            if self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(test_time):
