        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .CallsOnly()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.pending_signal = False
        self.pending_signal_time = None
        self.current_slice = None
        self.block_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime.astimezone(self.TimeZone).time()

        # Only use regular-session five-minute bars.
        if end_time < time(9, 35) or end_time > time(16, 0):
            return

        # Calculate the prior averages before adding the current completed bar.
        previous_ready = len(self.closes) >= self.slow_period
        if previous_ready:
            previous_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes) / self.slow_period
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(float(bar.Close))

        current_ready = len(self.closes) >= self.slow_period
        if not current_ready:
            return

        current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        bullish_cross = (
            previous_ready
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        if time(9, 45) <= end_time <= time(14, 30):
            self.pending_signal = True
            self.pending_signal_time = bar.EndTime

    def OnData(self, slice):
        self.current_slice = slice
        today = self.Time.date()

        self.HandleUnexpectedSpyPosition()

        # Expiration processing begins on the expiration date.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if today >= expiry_date:
                self.block_entry_date = today
                self.Debug(
                    f"Expiration processing: liquidating {self.held_option}"
                )
                self.SubmitOptionExit("expiration")
            elif (
                today == expiry_date - timedelta(days=1)
                and self.Time.time() >= time(15, 45)
            ):
                self.Debug(
                    f"Time stop: liquidating {self.held_option}"
                )
                self.SubmitOptionExit("pre-expiration time stop")

            self.EvaluateProfitTarget(slice)

        # Evaluate each crossover only once, after its completed bar.
        if self.pending_signal:
            self.pending_signal = False

            if (
                self.pending_signal_time is not None
                and self.pending_signal_time.date() == today
                and self.block_entry_date != today
            ):
                self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.block_entry_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None:
            status = self.entry_ticket.Status
            if status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]:
                return

        spy_bar = self.GetSliceBar(slice, self.spy.Symbol)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = float(spy_bar.Close)
        minimum_strike = 1.01 * spy_price
        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        chains = getattr(slice, "OptionChains", None)
        if chains is None:
            self.Debug("Skipped entry: option chain unavailable.")
            return

        contracts = []

        for chain in chains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date < minimum_expiry:
                    continue

                if contract.Strike >= minimum_strike:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"strike={selected.Strike}, expiry={selected.Expiry.date()}"
        )

    def EvaluateProfitTarget(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]:
                return

        quote = self.GetSliceQuote(slice, self.held_option)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.Debug(
                f"Profit target reached: {self.held_option}, "
                f"midpoint={midpoint:.2f}, entry={self.entry_price:.2f}"
            )
            self.SubmitOptionExit("50% profit target")

    def SubmitOptionExit(self, reason):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        quantity = holding.Quantity

        if quantity == 0:
            return

        self.CancelOpenExitOrder()

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=f"Option exit: {reason}"
        )

        self.Debug(
            f"Exit submitted: {self.held_option}, "
            f"quantity={-quantity}, reason={reason}"
        )

    def CancelOpenExitOrder(self):
        if self.exit_ticket is None:
            return

        status = self.exit_ticket.Status
        if status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            self.exit_ticket.Cancel("Replaced by newer exit condition")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.entry_ticket = None

                    self.Debug(
                        f"Entry filled: {self.held_option}, "
                        f"fill price={self.entry_price:.2f}"
                    )

                elif order_event.Status in [
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ]:
                    self.Debug("Entry order canceled or invalid.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol}, "
                        f"fill price={order_event.FillPrice:.2f}"
                    )
                    self.exit_ticket = None
                    self.held_option = None
                    self.entry_price = None

                elif order_event.Status in [
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ]:
                    self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.HandleUnexpectedExerciseOrAssignment("assignment")

    def OnAssignmentOrderEvent(self, assignment_event):
        self.HandleUnexpectedExerciseOrAssignment("assignment")

    def HandleUnexpectedExerciseOrAssignment(self, event_type):
        self.Debug(
            f"Unexpected option {event_type} handling: liquidating SPY."
        )
        self.block_entry_date = self.Time.date()
        self.HandleUnexpectedSpyPosition()

    def HandleUnexpectedSpyPosition(self):
        holding = self.Portfolio[self.spy.Symbol]

        if holding.Quantity != 0:
            self.block_entry_date = self.Time.date()
            self.Debug(
                f"Unexpected SPY equity position detected: "
                f"liquidating quantity {holding.Quantity}."
            )
            self.MarketOrder(
                self.spy.Symbol,
                -holding.Quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    @staticmethod
    def GetSliceBar(slice, symbol):
        bars = getattr(slice, "Bars", None)
        if bars is None:
            return None

        try:
            return bars[symbol] if symbol in bars else None
        except Exception:
            return None

    @staticmethod
    def GetSliceQuote(slice, symbol):
        quotes = getattr(slice, "QuoteBars", None)
        if quotes is None:
            return None

        try:
            return quotes[symbol] if symbol in quotes else None
        except Exception:
            return None

