from AlgorithmImports import *
from collections import deque
from datetime import timedelta, datetime


class ClockAlignedFiveMinuteAggregator:
    """Builds complete five-minute bars using New York minute-bar boundaries."""

    def __init__(self, callback):
        self.callback = callback
        self.bucket_end = None
        self.bars = []
        self.last_end = None

    def update(self, bar):
        end = bar.EndTime.replace(second=0, microsecond=0)
        minute = end.hour * 60 + end.minute
        bucket_end_minute = ((minute + 4) // 5) * 5
        bucket_end = end.replace(hour=0, minute=0) + timedelta(
            minutes=bucket_end_minute
        )

        if self.bucket_end != bucket_end:
            if self.bucket_end is not None:
                self._emit_if_complete()

            self.bucket_end = bucket_end
            self.bars = []
            self.last_end = None

        if self.last_end is not None:
            if end != self.last_end + timedelta(minutes=1):
                self.bars = []
            if end <= self.last_end:
                return

        self.bars.append(bar)
        self.last_end = end

        if end == self.bucket_end:
            self._emit_if_complete()
            self.bucket_end = None
            self.bars = []
            self.last_end = None

    def _emit_if_complete(self):
        if len(self.bars) != 5:
            return

        first = self.bars[0]
        last = self.bars[-1]

        consolidated = TradeBar(
            first.Time,
            first.Symbol,
            first.Open,
            max(x.High for x in self.bars),
            min(x.Low for x in self.bars),
            last.Close,
            sum(x.Volume for x in self.bars)
        )
        consolidated.Period = timedelta(minutes=5)
        self.callback(consolidated)


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.aggregator = ClockAlignedFiveMinuteAggregator(
            self._on_five_minute_bar
        )

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.blocked_entry_dates = set()
        self.time_stop_dates = set()

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_minute_exit_checks(slice)

        if self.spy.Symbol in slice.Bars:
            self.aggregator.update(slice.Bars[self.spy.Symbol])

    def _on_five_minute_bar(self, bar: TradeBar):
        self.fast_closes.append(float(bar.Close))
        self.slow_closes.append(float(bar.Close))

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end_time = bar.EndTime
        eligible_time = (
            bar_end_time.hour > 9
            or (bar_end_time.hour == 9 and bar_end_time.minute >= 45)
        ) and (
            bar_end_time.hour < 14
            or (bar_end_time.hour == 14 and bar_end_time.minute <= 30)
        )

        if bullish_cross and eligible_time:
            self._attempt_entry()

    def _attempt_entry(self):
        today = self.Time.date()

        if today in self.blocked_entry_dates:
            return

        if self.held_symbol is not None:
            return

        if self._is_open(self.entry_ticket):
            return

        if self._is_open(self.exit_ticket):
            return

        spy_price = float(self.Securities[self.spy.Symbol].Price)
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price")
            return

        candidates = []

        for chain in self.CurrentSlice.OptionChains:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                days_to_expiry = (expiry_date - today).days

                if days_to_expiry < 7:
                    continue

                if float(contract.Strike) < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no eligible call contract")
            return

        nearest_expiry = min(c.Expiry.date() for c in candidates)
        candidates = [
            c for c in candidates
            if c.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"strike={selected.Strike} expiry={nearest_expiry}"
        )

    def _process_minute_exit_checks(self, slice: Slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        today = self.Time.date()

        if self._is_expiration_processing_date(today):
            self.blocked_entry_dates.add(today)
            self._submit_exit("expiration protection")
            return

        if self._is_time_stop_date(today) and self.Time.hour == 15 and self.Time.minute == 45:
            if today not in self.time_stop_dates:
                self.time_stop_dates.add(today)
                self._submit_exit("expiration time stop")
            return

        contract = self._get_current_contract(slice, self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _get_current_contract(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains:
            for contract in chain.Contracts.Values:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = int(self.Portfolio[self.held_symbol].Quantity)
        if quantity <= 0:
            return

        if self._is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason} symbol={self.held_symbol}")

    def _is_time_stop_date(self, today):
        if self.held_symbol is None:
            return False

        expiry_date = self.held_symbol.ID.Date.date()
        previous_trading_day = expiry_date - timedelta(days=1)

        while not self.spy.Exchange.Hours.IsDateOpen(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        return today == previous_trading_day

    def _is_expiration_processing_date(self, today):
        if self.held_symbol is None:
            return False

        expiry_date = self.held_symbol.ID.Date.date()
        return today >= expiry_date

    def _is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        ]

    def OnOrderEvent(self, order_event: OrderEvent):
        status = order_event.Status

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {self.held_symbol} "
                    f"price={self.entry_price:.4f}"
                )
            elif status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ]:
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} "
                    f"price={float(order_event.FillPrice):.4f}"
                )

                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

            elif status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ]:
                self.exit_ticket = None

        order_type = getattr(order_event, "OrderType", None)
        is_exercise = order_type == OrderType.OptionExercise
        message = str(getattr(order_event, "Message", "")).lower()

        if is_exercise or "exercise" in message or "assignment" in message:
            self.blocked_entry_dates.add(self.Time.date())
            self.Debug(
                f"Unexpected exercise or assignment handling: "
