class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self._bucket_key = None
        self._bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.time_stop_date = None
        self.no_entry_date = None

        self.assignment_liquidation_pending = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()

        # Expiration protection is evaluated before any possible new entry.
        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.no_entry_date = current_date
                self._submit_exit("expiration protection")
            else:
                self._evaluate_open_position(slice)

        # Process SPY minute data into explicitly NY-aligned five-minute bars.
        if not slice.Bars.ContainsKey(self.spy):
            return

        minute_bar = slice.Bars[self.spy]
        self._process_minute_bar(minute_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        # Algorithm time is configured as New York time.
        end_time = self.Time.replace(second=0, microsecond=0)
        date = end_time.date()
        hour = end_time.hour
        minute = end_time.minute

        # Regular-session minute bars have ends from 09:31 through 16:00.
        if (hour < 9 or (hour == 9 and minute < 31) or
                hour > 16 or (hour == 16 and minute > 0)):
            return

        bucket_end_minute = ((minute - 1) // 5 + 1) * 5
        if bucket_end_minute > 60:
            return

        bucket_hour = hour
        if bucket_end_minute == 60:
            bucket_hour += 1
            bucket_end_minute = 0

        bucket_end = end_time.replace(
            hour=bucket_hour,
            minute=bucket_end_minute
        )
        bucket_key = bucket_end

        # A new bucket means the previous bucket is now complete.
        if self._bucket_key is not None and bucket_key != self._bucket_key:
            self._finalize_bucket(self._bucket_key, slice)

        if self._bucket_key != bucket_key:
            self._bucket_key = bucket_key
            self._bucket_bars = {}

        # Do not duplicate a minute if an unusual Slice contains it twice.
        self._bucket_bars[end_time] = minute_bar

        if len(self._bucket_bars) == 5:
            self._finalize_bucket(bucket_key, slice)

    def _finalize_bucket(self, bucket_end, slice: Slice):
        bars = self._bucket_bars

        if len(bars) != 5:
            # Missing minutes invalidate this five-minute bar.
            self.Debug(
                f"Skipped incomplete SPY five-minute bar ending "
                f"{bucket_end:%Y-%m-%d %H:%M}"
            )
        else:
            minute_times = sorted(bars.keys())
            expected = [
                bucket_end - timedelta(minutes=i)
                for i in range(4, -1, -1)
            ]

            if minute_times != expected:
                self.Debug(
                    f"Skipped non-contiguous SPY five-minute bar ending "
                    f"{bucket_end:%Y-%m-%d %H:%M}"
                )
            else:
                minute_bars = [bars[t] for t in minute_times]
                consolidated = TradeBar(
                    bucket_end - timedelta(minutes=5),
                    bucket_end,
                    self.spy,
                    minute_bars[0].Open,
                    max(x.High for x in minute_bars),
                    min(x.Low for x in minute_bars),
                    minute_bars[-1].Close,
                    sum(x.Volume for x in minute_bars),
                    timedelta(0)
                )
                self._on_five_minute_bar(consolidated, slice)

        self._bucket_bars = {}

    def _on_five_minute_bar(self, bar: TradeBar, slice: Slice):
        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period + 1:
            return

        previous_fast = sum(
            self.closes[-self.fast_period - 1:-1]
        ) / self.fast_period
        previous_slow = sum(
            self.closes[-self.slow_period - 1:-1]
        ) / self.slow_period

        current_fast = sum(
            self.closes[-self.fast_period:]
        ) / self.fast_period
        current_slow = sum(
            self.closes[-self.slow_period:]
        ) / self.slow_period

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        bar_time = bar.EndTime
        if hasattr(bar_time, "date"):
            bar_date = bar_time.date()
            bar_hour = bar_time.hour
            bar_minute = bar_time.minute
        else:
            bar_date = self.Time.date()
            bar_hour = self.Time.hour
            bar_minute = self.Time.minute

        eligible_time = (
            (bar_hour > 9 or (bar_hour == 9 and bar_minute >= 45)) and
            (bar_hour < 14 or (bar_hour == 14 and bar_minute <= 30))
        )

        if not bullish_cross or not eligible_time:
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self._is_open(self.entry_ticket):
            return

        self._try_enter(slice, float(bar.Close))

    def _try_enter(self, slice: Slice, spy_price: float):
        try:
            chain = slice.OptionChains[self.spy_option.Symbol]
        except KeyError:
            self.Debug("Skipped call selection: no current SPY option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not candidates:
            self.Debug("Skipped call selection: no eligible call contracts")
            return

        nearest_expiry = min(
            contract.Expiry.date() for contract in candidates
        )

        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug(
                "Skipped call selection: no call strike at least 1% OTM"
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry={nearest_expiry} strike={selected.Strike}"
        )

    def _evaluate_open_position(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        current_date = self.Time.date()
        expiry_date = self.held_symbol.ID.Date.date()

        # Trading day immediately preceding expiration.
        preceding_trading_day = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            preceding_trading_day
        ):
            preceding_trading_day -= timedelta(days=1)

        if (
            current_date == preceding_trading_day and
            (self.Time.hour > 15 or
             (self.Time.hour == 15 and self.Time.minute >= 45)) and
            self.time_stop_date != current_date
        ):
            self.time_stop_date = current_date
            self._submit_exit("expiration-eve time stop")
            return

        # Profit target requires a strictly positive current bid and ask.
        try:
            chain = slice.OptionChains[self.spy_option.Symbol]
        except KeyError:
            return

        contract = next(
            (x for x in chain if x.Symbol == self.held_symbol),
            None
        )

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self._is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.Debug(
            f"Exit submitted: {self.held_symbol} reason={reason}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled
        ):
            if (
                self.entry_ticket is not None and
                order_event.OrderId == self.entry_ticket.OrderId and
                order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                )
            ):
                self.entry_ticket = None
            return

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_symbol} "
                    f"price={self.entry_price}"
                )

            if order_event.Status == OrderStatus.Filled:
                self.entry_ticket = None

        elif (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.FillQuantity != 0:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice}"
                )

            if order_event.Status == OrderStatus.Filled:
                self.exit_ticket = None
                if self.held_symbol is not None:
                    if self.Portfolio[self.held_symbol].Quantity == 0:
                        self.held_symbol = None
                        self.entry_price = None
                        self.time_stop_date = None

        # Assignment/exercise can create SPY equity unexpectedly.
        if (
            order_event.Symbol == self.spy and
            order_event.FillQuantity != 0
        ):
            self.no_entry_date = self.Time.date()
            self.Debug(
                "Unexpected exercise or assignment created SPY equity; "
                "liquidating immediately"
            )
            self._liquidate_spy_equity()

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.no_entry_date = self.Time.date()
            self._liquidate_spy_equity()
        elif self.assignment_liquidation_pending:
            self.assignment_liquidation_pending = False

    def _liquidate_spy_equity(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        if not self.assignment_liquidation_pending:
            self.assignment_liquidation_pending = True
            self.Liquidate(self.spy)
            self.Debug("Submitted market liquidation for unexpected SPY equity")

    @staticmethod
    def _is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )
