from datetime import timedelta, time


class SpyBullishCallStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            fillForward=False
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option = option.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.closes = deque(maxlen=20)
        self.pending_signal = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.time_stop_date = None
        self.expiration_exit_submitted = False
        self.blocked_entry_date = None

        self.equity_liquidation_ticket = None

    def OnFiveMinuteBar(self, sender, bar):
        end = bar.EndTime

        # Only use complete regular-session bars aligned to New York boundaries.
        if end.time() < time(9, 35) or end.time() > time(16, 0):
            return

        if end.minute % 5 != 0 or end.second != 0:
            return

        if bar.StartTime.time() < time(9, 30):
            return

        # A missing interval produces no consolidated bar and therefore no update.
        if len(self.closes) >= 20:
            prior_fast = sum(list(self.closes)[-5:]) / 5.0
            prior_slow = sum(self.closes) / 20.0
        else:
            prior_fast = None
            prior_slow = None

        self.closes.append(float(bar.Close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        eligible_time = time(9, 45) <= end.time() <= time(14, 30)

        if (
            eligible_time
            and prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        ):
            self.pending_signal = {
                "date": end.date(),
                "price": float(bar.Close),
                "time": end
            }

    def OnData(self, slice):
        today = self.Time.date()

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing(today)

        # Evaluate each crossover exactly once, immediately after its bar closes.
        if self.pending_signal is not None:
            signal = self.pending_signal
            self.pending_signal = None

            if (
                self.held_option is None
                and not self.IsOpen(self.entry_ticket)
                and today != self.blocked_entry_date
            ):
                self.TryEnter(slice, signal["price"])

        self.ManageOpenPosition(slice)

    def TryEnter(self, slice, spy_price):
        if spy_price <= 0:
            self.Debug("Skipped option selection: invalid SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped option selection: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped option selection: no qualifying call contracts.")
            return

        expiries = sorted({contract.Expiry.date() for contract in contracts})
        expiry_date = expiries[0]

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiry_date
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug(
                f"Skipped option selection: no call strike >= 101% of SPY "
                f"for {expiry_date}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"strike={selected.Strike}, expiry={expiry_date}"
        )

    def ManageOpenPosition(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        today = self.Time.date()

        # The scheduled time stop applies independently of quote availability.
        if (
            self.time_stop_date is not None
            and today == self.time_stop_date
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("Trading-day-before-expiration time stop")
            return

        # Profit target requires a strictly positive current bid and ask.
        contract = self.GetCurrentContract(slice, self.held_option)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def HandleExpirationProcessing(self, today):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()

        if today >= expiry_date:
            self.blocked_entry_date = today

            quantity = self.Portfolio[self.held_option].Quantity
            if quantity > 0 and not self.expiration_exit_submitted:
