        self.CancelOpenExitOrder()

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

        self.Debug(
            f"Exit submitted: {self.held_option}, quantity={quantity}, "
            f"reason={reason}"
        )

    def CancelOpenExitOrder(self):
        if self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by higher-priority liquidation")

    def GetCurrentContract(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if not self.IsOpen(self.equity_liquidation_ticket):
            self.Debug(
                f"Unexpected SPY equity position detected: quantity={quantity}; "
                "liquidating immediately."
            )
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise/assignment equity liquidation"
            )

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and orderEvent.OrderId == self.entry_ticket.OrderId
                and orderEvent.FillQuantity > 0
            ):
                self.held_option = orderEvent.Symbol
                self.entry_price = float(orderEvent.FillPrice)
                self.time_stop_date = self.GetPreviousTradingDay(
