                self.exit_ticket is not None
                and orderEvent.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    f"Exit filled: {orderEvent.Symbol}, "
                    f"fill price={orderEvent.FillPrice}"
                )
                self.ClearOptionState()

            elif (
                self.equity_liquidation_ticket is not None
                and orderEvent.OrderId == self.equity_liquidation_ticket.OrderId
            ):
