    def OnFiveMinuteBar(self, sender, bar):
        bar_end = bar.EndTime

        # Keep bars aligned to New York regular-session five-minute boundaries.
        if bar_end.date() != bar.Time.date():
            return

        if bar_end.time() < time(9, 35) or bar_end.time() > time(16, 0):
            return

        if bar_end.minute % 5 != 0:
            return

        if bar.Time != bar_end - timedelta(minutes=5):
            return

        # Do not use a bar after a missing interval.
        if self.last_accepted_bar_end is not None:
            if bar_end != self.last_accepted_bar_end + timedelta(minutes=5):
                self.last_accepted_bar_end = None
                return

        if self.last_accepted_bar_end is None and bar_end.time() != time(9, 35):
