    def HandleUnexpectedAssignment(self):
        self.Debug(
            f"Unexpected exercise or assignment at {self.Time}; "
            "liquidating SPY equity."
        )
        holding = self.Portfolio[self.spy.Symbol]
        if holding.Invested:
            self.MarketOrder(self.spy.Symbol, -holding.Quantity)
        self.no_entry_date = self.Time.date()

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

    def CancelOpenExitOrder(self):
        if self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Replacing exit order")

    def GetPreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate
