            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.SubscriptionManager.AddConsolidator("SPY", self.consolidator)
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = None
        self.last_spy_close = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.expiration_block_date = None
        self.last_time_stop_date = None
        self.assignment_liquidation_submitted = False

    def OnFiveMinuteBar(self, sender, bar):
        local_end = bar.EndTime

        if local_end.date() < self.StartDate.date():
            return

        if local_end.time() < time(9, 35) or local_end.time() > time(16, 0):
            return

        # Regular-session five-minute bars must end on five-minute boundaries.
        if local_end.minute % 5 != 0:
            return

        self.last_spy_close = float(bar.Close)

        self.fast_values.append(float(bar.Close))
        self.slow_values.append(float(bar.Close))

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        current_fast = sum(self.fast_values) / 5.0
        current_slow = sum(self.slow_values) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.pending_signal = None
        if (
            bullish_cross
            and time(9, 45) <= local_end.time() <= time(14, 30)
        ):
            self.pending_signal = local_end

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def OnData(self, slice):
        current_date = self.Time.date()

        self.HandleExpirationProcessing()
        self.HandleUnexpectedEquityPosition()
        self.ManageOpenOption(slice)

        if self.pending_signal is not None:
            signal_time = self.pending_signal
            self.pending_signal = None

            if signal_time.date() == current_date:
                self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.expiration_block_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if self.last_spy_close is None:
            self.Debug("Skipped selection: SPY price unavailable.")
            return

        selected = self.SelectCall(slice, self.last_spy_close)
        if selected is None:
            self.Debug("Skipped selection: no qualifying SPY call.")
            return

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def SelectCall(self, slice, spy_price):
        minimum_expiry = self.Time.date() + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date < minimum_expiry:
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            return None

        candidates.sort(
            key=lambda contract: (
                contract.Expiry.date(),
                contract.Strike,
                str(contract.Symbol)
            )
        )
        return candidates[0]

    def ManageOpenOption(self, slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if (
            self.Time.date() == expiry_date - timedelta(days=1)
            and self.Time.time() == time(15, 45)
            and self.last_time_stop_date != self.Time.date()
        ):
            self.last_time_stop_date = self.Time.date()
            self.SubmitExit("time stop")
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        quote = self.GetCurrentQuote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("profit target")

    def GetCurrentQuote(self, slice, symbol):
        if not slice.QuoteBars.ContainsKey(symbol):
            return None

        quote_bar = slice.QuoteBars[symbol]
        if quote_bar.Bid is None or quote_bar.Ask is None:
            return None

        return float(quote_bar.Bid.Close), float(quote_bar.Ask.Close)

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.exit_ticket.Cancel("Replacing with liquidation order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted ({}): {}".format(reason, self.held_symbol)
        )

    def HandleExpirationProcessing(self):
        if self.held_symbol is None:
            return

        security = self.Securities[self.held_symbol]
        expiry_date = security.Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.expiration_block_date = self.Time.date()
            self.pending_signal = None

            if self.Portfolio[self.held_symbol].Invested:
                self.SubmitExit("expiration protection")

    def HandleUnexpectedEquityPosition(self):
        spy_holding = self.Portfolio["SPY"]

        if spy_holding.Quantity != 0:
            if not self.assignment_liquidation_submitted:
                self.Debug(
                    "Unexpected exercise or assignment: liquidating SPY."
                )
                self.MarketOrder("SPY", -spy_holding.Quantity)
                self.assignment_liquidation_submitted = True
        else:
            self.assignment_liquidation_submitted = False

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.entry_ticket = None

            self.Debug(
                "Entry filled: {} at {:.4f}".format(
                    self.held_symbol,
                    self.entry_price
                )
            )
            return

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            self.Debug("Exit filled: {}".format(order_event.Symbol))
            self.exit_ticket = None

            if self.held_symbol is not None:
                if not self.Portfolio[self.held_symbol].Invested:
                    self.held_symbol = None
                    self.entry_price = None

            return

        is_assignment = getattr(order_event, "IsAssignment", False)
        is_exercise = (
            order_event.OrderType == OrderType.OptionExercise
        )

        if is_assignment or is_exercise:
            self.Debug(
                "Unexpected exercise or assignment event: {}".format(
                    order_event.Symbol
                )
            )
            self.HandleUnexpectedEquityPosition()
